package br.com.bancohorizonte.service;
import br.com.bancohorizonte.dto.*; import br.com.bancohorizonte.entity.*; import br.com.bancohorizonte.exception.*; import br.com.bancohorizonte.repository.*; import jakarta.persistence.*; import java.math.BigDecimal; import java.util.*;
public class ContaService { private final EntityManager em; private final PessoaRepository pessoas; private final TipoContaRepository tipos; private final ContaBancariaRepository contas; private final MovimentacaoService movimentacao=new MovimentacaoService(); public ContaService(EntityManager em){this.em=em;pessoas=new PessoaRepository(em);tipos=new TipoContaRepository(em);contas=new ContaBancariaRepository(em);} public ContaResponse abrir(AbrirContaRequest r){validarAbertura(r);EntityTransaction tx=em.getTransaction();try{tx.begin();if(contas.existeAgenciaENumero(r.agencia(),r.numero()))throw new ContaJaCadastradaException(r.agencia(),r.numero());Pessoa p=pessoas.porId(r.titularId()).orElseThrow(()->new PessoaNaoEncontradaException(r.titularId()));TipoConta t=tipos.porId(r.tipoContaId()).orElseThrow(()->new TipoContaNaoEncontradoException(r.tipoContaId()));ContaBancaria c=new ContaBancaria(r.agencia(),r.numero(),r.saldoInicial(),r.ativa(),p,t);contas.salvar(c);tx.commit();return map(c);}catch(RuntimeException e){rollback(tx);throw e;}} public ContaResponse buscar(Long id){return map(contas.porIdComRelacoes(id).orElseThrow(()->new ContaNaoEncontradaException(id)));} public List<ContaResponse> listarPorPessoa(Long pessoaId){if(!pessoas.porId(pessoaId).isPresent())throw new PessoaNaoEncontradaException(pessoaId);return contas.porPessoa(pessoaId).stream().map(this::map).toList();} public ContaResponse depositar(Long id,BigDecimal valor){return movimentar(id,valor,true);} public ContaResponse sacar(Long id,BigDecimal valor){return movimentar(id,valor,false);} private ContaResponse movimentar(Long id,BigDecimal valor,boolean deposito){EntityTransaction tx=em.getTransaction();try{tx.begin();ContaBancaria c=contas.porIdComRelacoes(id).orElseThrow(()->new ContaNaoEncontradaException(id));if(deposito)movimentacao.depositar(c,valor);else movimentacao.sacar(c,valor);tx.commit();return map(c);}catch(RuntimeException e){rollback(tx);throw e;}} private void rollback(EntityTransaction tx){if(tx.isActive())tx.rollback();} private void validarAbertura(AbrirContaRequest r){if(r==null||r.agencia()==null||!r.agencia().matches("\\d{4}")||r.numero()==null||!r.numero().matches("\\d{6}-\\d")||r.saldoInicial()==null||r.saldoInicial().compareTo(BigDecimal.ZERO)<0||r.titularId()==null||r.tipoContaId()==null)throw new BusinessException("Dados para abertura de conta inválidos.");} private ContaResponse map(ContaBancaria c){return new ContaResponse(c.getId(),c.getAgencia(),c.getNumero(),c.getSaldo(),c.isAtiva(),new TitularResponse(c.getTitular().getId(),c.getTitular().getNome()),new TipoContaResponse(c.getTipoConta().getId(),c.getTipoConta().getNome()));} }
